        "pergunta": "Recém-nascido, sexo genético feminino (46, XX), apresenta genitália ambígua (escala de Prader III). No 10º dia de vida, evolui com recusa alimentar, vômitos, desidratação grave e choque. Exames revelam sódio de 118 mEq/L, potássio de 7,2 mEq/L e hipoglicemia.\n\nITEM A: Qual o diagnóstico sindrômico e a deficiência enzimática mais comum responsável por este quadro?\nITEM B: Qual hormônio encontra-se fortemente elevado e é utilizado como marcador no teste de triagem neonatal (Teste do Pezinho)?",
        "gabarito": "ITEM A: Hiperplasia Adrenal Congênita (forma perdedora de sal). Deficiência da enzima 21-hidroxilase.\n\nITEM B: 17-OH-progesterona (17-hidroxiprogesterona)."
