        "gabarito": "ITEM A: A dose de hidrocortisona deve ser dobrada ou triplicada (dose de estresse) enquanto durar o quadro de estresse/infecção (ou realizar ataque EV de 100mg/m² se não tolerar via oral).\n\nITEM B: Não. Não é necessário dobrar a dose da fludrocortisona em situações de estresse intercorrente."
