        "gabarito": "ITEM A: Como o tratamento materno foi finalizado a menos de 30 dias do parto, ele é considerado inadequado. Portanto, o RN é notificado como caso de Sífilis Congênita.\n\nITEM B: Deve-se coletar hemograma, radiografia de ossos longos e punção lombar (LCR). O tratamento obrigatório é com Penicilina Cristalina (ou procaína se liquor normal) por 10 dias, independentemente dos resultados dos exames."
