        "gabarito": "ITEM A: Motor grosso: Senta-se (com apoio ou iniciando sentar sem apoio) / rola. Motor fino: Pega objetos (transferência de objetos de uma mão para outra). Social/Adaptativo: Reconhece familiares / estranha pessoas não familiares / atende pelo nome.\n\nITEM B: Trata-se de um provável atraso (perda de marco de faixa etária anterior, já que o sustento cefálico deve ocorrer até 3-4 meses). A conduta é encaminhar imediatamente para avaliação em rede de atenção especializada/multidisciplinar."
