        "pergunta": "A literatura médica atual enfatiza amplamente o impacto negativo do 'estresse tóxico' e da exposição precoce às telas no neurodesenvolvimento durante a Janela de Oportunidades (primeiros mil dias).\n\nITEM A: Qual é a recomendação oficial da SBP sobre o tempo de tela para crianças menores de 2 anos?\nITEM B: Descreva sucintamente como o estresse tóxico prolongado na primeira infância atua na neurotoxicidade (fisiopatologia) e cite uma possível consequência neurológica.",
