        "pergunta": "Escolar de 5 anos, com Fibrose Cística (mutação DeltaF508 homozigota), apresenta tosse crônica diária e está no terceiro episódio de exacerbação pulmonar no ano. Sua radiografia de tórax evidencia impactação de muco e áreas iniciais de bronquiectasias.\n\nITEM A: Qual é o defeito primário na fisiopatologia da fibrose cística que leva à doença pulmonar e gastrointestinal?\nITEM B: Cite 3 (três) agentes etiológicos bacterianos que colonizam e infectam comumente as vias aéreas dos pacientes com fibrose cística.",
        "gabarito": "ITEM A: Mutação genética (CFTR) que causa disfunção no canal de transporte de Cloreto (e bicarbonato) transmembrana, gerando secreções desidratadas e espessas/viscosas.\n\nITEM B: Staphylococcus aureus, Pseudomonas aeruginosa e Haemophilus influenzae (também aceitos Burkholderia cepacia)."
