        "gabarito": "ITEM A: Crise Febril Simples. Não há indicação de realizar coleta de líquor (LCR), eletroencefalograma ou neuroimagem para crises febris simples.\n\nITEM B: Nenhuma. Não há recomendação de tratamento profilático contínuo com antiepilépticos na crise febril simples, devendo-se apenas tranquilizar os pais."
