        "gabarito": "ITEM A: Cólica do lactente. Critérios: idade inferior a 5 meses; períodos prolongados e recorrentes de choro, desconforto ou irritabilidade sem uma causa evidente; cuidadores incapazes de solucionar a sintomatologia; ganho de peso normal e ausência de febre ou outras doenças.\n\nITEM B: Tranquilizar e acolher os pais, explicando a natureza benigna e transitória do quadro, investigando e atuando nas vulnerabilidades familiares.\n\nITEM C: Em algumas situações de choro prolongado, pode ser tentada a restrição materna do uso de proteínas do leite de vaca (ou uso de fórmula extensamente hidrolisada para não amamentados), realizando o desafio diagnóstico 4 a 12 semanas após."
