        "pergunta": "Adolescente, masculino, 14 anos, acompanhado e tratado em serviço público com diagnóstico de Doença de Hodgkin há 3 anos, recebe alta por cura. Procura seu pediatra acompanhado de sua mãe e solicita cópia do prontuário, pois irá se mudar de estado. O pediatra nega o acesso, informando que sua caligrafia é ruim e também porque no prontuário há termos médicos, cujo entendimento do paciente pode não ser adequado. Três anos após o pediatra precisa responder um processo no CRM, envolvendo o caso do paciente. Ele vai ao SAME do hospital e efetua cópia do prontuário para sua defesa.\n\nITEM A: O médico agiu corretamente em relação ao pedido de seu paciente, ao não fornecer acesso e cópia do prontuário? Justifique.\nITEM B: O médico pode efetuar cópia de prontuário para sua própria defesa? Justifique.",
        "gabarito": "ITEM A: Não. Segundo o Código de Ética Médica, é vedado ao médico negar ao paciente (ou representante legal) acesso ao seu prontuário, deixar de lhe fornecer cópia quando solicitada ou deixar de dar explicações necessárias, salvo quando ocasionarem riscos ao paciente ou a terceiros (Art. 88).\n\nITEM B: Sim. É vedado ao médico liberar cópias do prontuário sob sua guarda, *exceto* para atender ordem judicial ou para sua *própria defesa* (Art. 89), devendo solicitar que seja observado o sigilo profissional."
