        "gabarito": "ITEM A: Intolerância à lactose (secundária/transitória pós-gastroenterite).\n\nITEM B: Teste do hidrogênio expirado (respiratório) ou medição da atividade da lactase em fragmento de biópsia.\n\nITEM C: Não é obrigatório, pois a conduta inicial e o teste podem ser estritamente clínicos, retirando temporariamente a lactose da dieta e avaliando a melhora dos sintomas.\n\nITEM D: Exclusão ou redução de leite e derivados com lactose da dieta (usar produtos zero lactose, fórmulas adequadas) e, opcionalmente, o uso da enzima lactase exógena antes da ingestão para abreviar os sintomas."
