        "gabarito": "Hipótese: Intolerância à lactose. A intolerância secundária à lactose segue-se à lesão da mucosa do intestino delgado (Doença Celíaca, gastroenterite aguda grave) e geralmente é transitória, melhorando com a cicatrização da mucosa.\n\nMétodo: A deficiência de lactase pode ser diagnosticada pelo teste H2 respiratório (2g/kg até 25g) ou pela medição da atividade da lactase no tecido mucoso obtido por biópsia do intestino delgado.\n\nNecessidade: Os testes de diagnóstico não são obrigatórios e, muitas vezes, simples mudanças na dieta que reduzem ou eliminam a lactose da dieta aliviam os sintomas.\n\nTratamento: O tratamento da deficiência de lactase consiste em uma dieta sem leite. Uma fórmula sem lactose (à base de soja ou leite de vaca) pode ser usada em bebês. Em crianças mais velhas, o leite com baixo teor de lactose pode ser consumido. A adição de lactase aos produtos lácteos geralmente abrevia os sintomas."
