        "informacoesComplementares": "<strong>Comentário:</strong> Segundo a Organização Mundial da Saúde, o aleitamento materno predominante ocorre quando a criança recebe leite materno como principal alimento, mas também recebe água, chás, infusões, sucos ou outros líquidos à base de água. A oferta de chá impede que a criança seja classificada como em aleitamento materno exclusivo.\n\n<strong>Pérolas de prova:</strong>\n• Aleitamento materno exclusivo = apenas leite materno.\n• Aleitamento materno predominante = leite materno + água, chás, infusões ou sucos.\n• Aleitamento materno complementado = leite materno + alimentos sólidos ou semissólidos.\n• Aleitamento materno misto (parcial) = leite materno + outro tipo de leite."
