        "gabarito": "Gabarito oficial: Opção C",
        "informacoesComplementares": "<strong>Comentário:</strong> A síndrome torácica aguda é definida pela presença de infiltrado pulmonar novo associado a sintomas respiratórios em pacientes com doença falciforme. É uma das principais emergências da doença e a principal causa de mortalidade nesses pacientes.\n\n<strong>Pérolas de prova:</strong>\n• Todo infiltrado pulmonar novo em paciente falcêmico deve levantar suspeita de síndrome torácica aguda.\n• Febre, dor torácica e hipoxemia são manifestações frequentes.\n• A evolução pode ser rápida para insuficiência respiratória.\n• É a principal causa de mortalidade da doença falciforme."
