        "gabarito": "Gabarito oficial: Opção C",
        "informacoesComplementares": "<strong>Comentário:</strong> Controle e gravidade são conceitos distintos. O controle representa a situação clínica atual do paciente. Já a gravidade é determinada retrospectivamente, de acordo com a intensidade do tratamento necessária para manter esse controle.\n\n<strong>Pérolas de prova:</strong>\n• Controle ≠ gravidade.\n• A gravidade é definida após tratamento otimizado.\n• Um paciente pode ter asma grave e estar completamente controlado."
