        "informacoesComplementares": "<strong>Comentário:</strong> O controle da asma é avaliado por quatro parâmetros nas últimas quatro semanas: sintomas diurnos, despertares noturnos, necessidade de medicação de alívio e limitação das atividades. A presença de três ou quatro critérios caracteriza asma não controlada.\n\n<strong>Pérolas de prova:</strong>\n• O GINA avalia as últimas quatro semanas.\n• Quatro perguntas definem o controle.\n• 0 critérios = controlada.\n• 1–2 critérios = parcialmente controlada.\n• 3–4 critérios = não controlada."
