        "informacoesComplementares": "<strong>Comentário:</strong> A coarctação grave costuma manifestar-se após o fechamento do ducto arterioso. O achado clássico é a discrepância entre pulsos e pressão arterial dos membros superiores e inferiores. Nos recém-nascidos, pode evoluir rapidamente para choque cardiogênico e acidose metabólica.\n\n<strong>Pérolas de prova:</strong>\n• Fechamento do ducto → descompensação.\n• Pulsos femorais diminuídos.\n• Diferença de PA entre membros superiores e inferiores.\n• Cardiopatia ducto-dependente."
