        "informacoesComplementares": "<strong>Comentário:</strong> Na transposição das grandes artérias, a sobrevivência depende da mistura entre as circulações sistêmica e pulmonar. A infusão de prostaglandina E1 mantém a patência do ducto arterioso e melhora a oxigenação até o tratamento definitivo.\n\n<strong>Pérolas de prova:</strong>\n• TGA = duas circulações paralelas.\n• PGE1 deve ser iniciada imediatamente.\n• Rashkind quando a mistura é insuficiente.\n• Cirurgia de Jatene nas primeiras duas semanas de vida."
