        "informacoesComplementares": "<strong>Comentário:</strong> A crise hipercianótica (\"tet spell\") decorre da redução abrupta do fluxo pulmonar. A posição genupeitoral aumenta a resistência vascular sistêmica e favorece o fluxo para os pulmões, sendo a primeira medida terapêutica, seguida de oxigênio, sedação e outras intervenções conforme a resposta clínica.\n\n<strong>Pérolas de prova:</strong>\n• Choro é desencadeante frequente.\n• Primeira medida = posição joelho-tórax.\n• O sopro pode diminuir durante a crise.\n• Crises prolongadas podem causar AVC e convulsões."
