        "gabarito": "Gabarito oficial: Opção B",
        "informacoesComplementares": "<strong>Comentário:</strong> Os principais achados do atraso constitucional do crescimento são: • história familiar de puberdade tardia; • velocidade de crescimento preservada; • idade óssea atrasada; • puberdade tardia; • estatura final geralmente normal. Já na baixa estatura familiar, a idade óssea costuma ser compatível com a idade cronológica.\n\n<strong>Pérolas de prova:</strong>\n• Idade óssea atrasada → atraso constitucional ou doença endócrina.\n• História familiar de puberdade tardia favorece atraso constitucional.\n• Baixa estatura familiar → idade óssea normal.\n• Atraso constitucional → altura final geralmente normal."
