        "informacoesComplementares": "<strong>Comentário:</strong> Após o tratamento, a alta é segura quando a criança apresenta: • ausência de estridor em repouso; • saturação normal; • boa entrada de ar; • nível de consciência normal; • recebeu corticosteroide; • permaneceu em observação por 2–3 horas após a adrenalina nebulizada. Radiografia e antibióticos não fazem parte da rotina.\n\n<strong>Pérolas de prova:</strong>\n• Observar por 2–3 horas após adrenalina.\n• Alta apenas sem estridor em repouso.\n• Radiografia não é exame de rotina.\n• A 3ª questão praticamente responde metade da discursiva."
