        "pergunta": "Menina de 8 anos encontra-se no 5º dia de dengue. A febre desapareceu há poucas horas. Evoluiu com dor abdominal intensa, vômitos persistentes e irritabilidade. O hematócrito aumentou em relação ao exame realizado no dia anterior e as plaquetas reduziram progressivamente. A interpretação correta desse quadro é:",
