        "gabarito": "Gabarito oficial: Opção C",
        "informacoesComplementares": "<strong>Comentário:</strong> Os Critérios de Jones revisados pela American Heart Association em 2015 permanecem a base do diagnóstico da febre reumática aguda. Para um primeiro episódio, exige-se evidência de infecção recente pelo estreptococo do grupo A associada a dois critérios maiores ou um critério maior e dois critérios menores. Entre as atualizações mais importantes está a inclusão da cardite subclínica detectada ao ecocardiograma como critério maior.\n\n<strong>Pérolas de prova:</strong>\n• Jones revisado (AHA 2015).\n• Evidência de infecção por GAS é obrigatória.\n• 2 maiores OU 1 maior + 2 menores.\n• Cardite subclínica conta como critério maior.\n• A terceira forma (3 menores) aplica-se apenas a recorrência em populações de risco moderado/alto."
