        "gabarito": "Gabarito oficial: Opção C",
        "informacoesComplementares": "<strong>Comentário:</strong> Embora a hipertensão primária esteja se tornando cada vez mais frequente em adolescentes obesos, crianças menores com hipertensão importante exigem investigação de causas secundárias. A coarctação da aorta é uma das principais causas cardiovasculares de hipertensão na infância. A diminuição dos pulsos femorais e a diferença pressórica entre membros superiores e inferiores constituem achados clássicos, motivo pelo qual a medida da pressão arterial nos quatro membros faz parte da investigação inicial de toda criança com hipertensão confirmada.\n\n<strong>Pérolas de prova:</strong>\n• Criança pequena + HAS importante = pensar em HAS secundária.\n• Doença renal responde por cerca de 90% das causas secundárias.\n• Coarctação da aorta é diagnóstico obrigatório.\n• Medir PA nos quatro membros.\n• Pulsos femorais diminuídos são pista clássica."
