        "gabarito": "Gabarito oficial: Opção B",
        "informacoesComplementares": "<strong>Comentário:</strong> O preenchimento correto da Declaração de Óbito exige reconstrução da cadeia causal da morte. A linha a deve conter a causa imediata (por exemplo, insuficiência respiratória aguda ou CIVD, conforme a evolução clínica), seguida das complicações intermediárias, terminando na doença que iniciou todo o processo, como meningite bacteriana ou encefalite, dependendo do caso.\n\n<strong>Pérolas de prova:</strong>\n• Pensar sempre em cadeia causal.\n• A causa básica é a doença que iniciou o processo.\n• Não utilizar \"parada cardiorrespiratória\".\n• Um diagnóstico por linha.\n• A Parte II não faz parte da sequência causal."
