        "informacoesComplementares": "<strong>Comentário:</strong> A presença de petéquias ou púrpura em uma criança com suspeita de meningite deve levantar imediatamente a hipótese de meningococcemia. A doença meningocócica pode evoluir rapidamente para choque, coagulação intravascular disseminada e óbito. Embora pneumococo seja atualmente a principal causa de meningite bacteriana em muitos países, o exantema petequial e purpúrico é característico da infecção por Neisseria meningitidis.\n\n<strong>Pérolas de prova:</strong>\n• Petéquias + meningite = pensar em meningococo.\n• Meningococcemia pode evoluir rapidamente para choque.\n• CIVD é complicação frequente.\n• Emergência médica."
